common_types_ts:
// Existing imports from contracts.ts and ports.ts; no new shared DTO/port files.
// B4 exports these structural types from queue.ts. B3 declares identical structural types
// locally, so B4 never imports the unfinished B3 service and workers can compile separately.
export type PreparedBudgetContext = Readonly<{
  accountEvidenceId: string; budgetQuoteId: string; policyId: string;
  expectedPolicyRevision: number; expectedAuthorizationRevision: number;
  expectedQuoteInputHash: string; executionSemanticHash: string; credentialBindingId: string;
}>;
export type ReserveSubmission = (
  tx: ProductionWritePort, currentJob: ProductionJob, quote: ProductionQuote,
  capability: CapabilityReceipt, now: number, context: PreparedBudgetContext
) => BudgetReservation;
export type SubmissionAdmission = Readonly<{
  quote: ProductionQuote; capability: CapabilityReceipt; eligibilityFingerprint: string;
  context: PreparedBudgetContext; reserve: ReserveSubmission; outbox: OutboxIntent;
}>;
// Replace old beginSubmission(job,lease,now); no caller-sampled now parameter.
// Existing constructor(store, now=Date.now) stays unchanged.
beginSubmission(job: ProductionJob, lease: JobLease, admission: SubmissionAdmission): ProductionJob | null;
// ProductionWorkerOptions replacement; all unrelated options unchanged.
prepareBudgetContext?: (job: ProductionJob, quote: ProductionQuote, capability: CapabilityReceipt) => Promise<PreparedBudgetContext>;
reserveSubmission?: ReserveSubmission;
// Remove authorizeSubmission. Missing either replacement blocks without reserve/submit.

B3_factory_ts:
export type BudgetScopeRequest = Pick<MoneyScope, "providerId" | "unit" | "currency">;
export type AccountBudgetPolicyCommand = z.infer<typeof AccountBudgetPolicyCommandSchema>;
export type CreateAccountPolicyCommand = BudgetScopeRequest & Pick<AccountBudgetPolicy, "dailyCap" | "expiresAt" | "revoked" | "actorId">;
export type TrustedAccountIdentity = Readonly<{
  providerId: string; accountId: string; accountEvidenceId: string; credentialBindingId: string;
}>;
export type TrustedPreparedExecutionEvidence = Readonly<{
  accountEvidenceId: string; budgetQuoteId: string; expectedQuoteInputHash: string;
  executionSemanticHash: string; credentialBindingId: string;
}>;
export interface BudgetServiceOptions {
  store: ProductionStore;
  resolveAccountIdentity?: (providerId: string) => Promise<TrustedAccountIdentity>;
  prepareExecutionEvidence?: (input: Readonly<{execution: BudgetExecution; budgetQuoteId: string}>) => Promise<TrustedPreparedExecutionEvidence>;
  currentCredentialBindingId?: (providerId: string) => string | null;
  produceReconciliationEvidence?: (input: Readonly<{reservation: BudgetReservation; reference: string}>) => Promise<ReconciliationEvidence>;
  now?: () => number; idFactory?: () => string;
}
export interface ProductionBudgetService {
  createPolicy(projectId: string, command: CreateAccountPolicyCommand): Promise<AccountBudgetPolicy>;
  updatePolicy(projectId: string, scope: BudgetScopeRequest, command: AccountBudgetPolicyCommand): Promise<AccountBudgetPolicy>;
  authorizeProject(projectId: string, scope: BudgetScopeRequest, command: AuthorizeBudgetCommand): Promise<BudgetAuthorization>;
  getReadModel(projectId: string, scope: BudgetScopeRequest): Promise<ProjectBudgetReadModel>;
  prepareBudgetContext(execution: BudgetExecution, budgetQuoteId: string): Promise<PreparedBudgetContext>;
  reserveInTransaction(tx: ProductionWritePort, execution: BudgetExecution, now: number, context: PreparedBudgetContext): BudgetReservation;
  reconcile(reservationId: string, reference: string): Promise<StoredEvidence>;
}
export function createProductionBudgetService(options: BudgetServiceOptions): ProductionBudgetService;
// Service file owns injectable HTTP factory too, avoiding unsupported extra Next route exports.
export interface BudgetRouteHandlerOptions {
  withStore?: <T>(work: (store: ProductionStore) => T | Promise<T>) => Promise<T>;
  serviceOptions?: Omit<BudgetServiceOptions, "store">;
}
export function createBudgetRouteHandlers(options?: BudgetRouteHandlerOptions): {
  GET(request: Request, context: {params: Promise<{projectId: string}>}): Promise<Response>;
  POST(request: Request, context: {params: Promise<{projectId: string}>}): Promise<Response>;
};
// route.ts imports factory and exports only GET/POST; default withStore wraps withProductionStore.

http.POST_ts:
type BudgetRouteCommand =
 | ({kind: "create_policy"} & CreateAccountPolicyCommand)
 | ({kind: "update_policy"; command: AccountBudgetPolicyCommand} & BudgetScopeRequest)
 | ({kind: "authorize"; command: AuthorizeBudgetCommand} & BudgetScopeRequest);
// strict discriminated zod objects; nested commands use existing B1 strict schemas.
// JSON currency is required nullable: null only for spark_token.
// create has no policyId/expected revision; service generates policyId and uses CAS null.
// update command expectedPolicyRevision must be positive (null rejected for update).
// authorize expectedAuthorizationRevision nullable retains B1 create/update CAS semantics.

read_model_ts:
type BudgetPolicyView = Omit<AccountBudgetPolicy, "accountId">;
type BudgetAuthorizationView = BudgetAuthorization;
type BudgetReadReason = "ACCOUNT_IDENTITY_UNAVAILABLE" | "POLICY_MISSING" | "AUTHORIZATION_MISSING" | "EVIDENCE_MISSING_OR_STALE" | "ACCOUNT_BINDING_MISMATCH" | "POLICY_REVOKED" | "POLICY_EXPIRED" | "POLICY_NOT_YET_VALID" | "POLICY_CAP_UNKNOWN" | "DAILY_CAP_BLOCKED" | "AUTHORIZATION_REVOKED" | "AUTHORIZATION_EXPIRED" | "AUTHORIZATION_NOT_YET_VALID" | "PROJECT_CAP_UNKNOWN" | "PROJECT_CAP_BLOCKED" | "TOTALS_INVALID";
export interface ProjectBudgetReadModel {
  schemaVersion: 1; projectId: string; scope: BudgetScopeRequest; utcDay: string;
  availability: "available" | "unavailable";
  policy: BudgetPolicyView | null; authorization: BudgetAuthorizationView | null;
  projectTotals: BudgetSummary | null; accountDailyTotals: BudgetSummary | null;
  unresolved: boolean | null; overrun: boolean | null; reconciliationConflict: boolean | null;
  reasons: BudgetReadReason[];
}
// available means trusted account scope/totals readable, not permission for a specific execution.
// Unknown account => unavailable, null totals/flags, ACCOUNT_IDENTITY_UNAVAILABLE.
// Missing caps remain null and reasons; never synthesize 0 or reset ledger.
